  ?z brick:hasPoint ?tPoint .
  ?tPoint a brick:AirTemperature ; ref:hasTimeseriesId ?ts .
  BIND(STR(?z) AS ?zName)
}
LIMIT 20

SELECT ?zName WHERE {
  ?z a brick:Zone .
  BIND(STR(?z) AS ?zName)
}
LIMIT 20

SELECT ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
} LIMIT 20

SELECT ?zone ?p ?ptype ?ts WHERE {
  ?zone brick:hasPoint ?p .
  ?p ref:hasTimeseriesId ?ts .
  ?p a ?ptype .
  FILTER(STRSTARTS(STR(?zone), "http://buildgraph.org/BG_medium_office_2004_0000#Room"))
} LIMIT 200

SELECT ?zone ?p ?ptype ?ts WHERE {
  ?zone brick:hasPoint ?p .
  ?p a ?ptype .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
  FILTER(STRSTARTS(STR(?zone), "http://buildgraph.org/BG_medium_office_2004_0000#Room"))
} LIMIT 200

